    { "step": 6, "action": "spatial_join", "database": null, "purpose": "Filter those buildings to those also intersecting flood hazard polygons (intersects)" },
    { "step": 7, "action": "sort", "database": null, "purpose": "Sort results by bygningid ascending" },
    { "step": 8, "action": "limit", "database": null, "purpose": "Limit to 10 buildings" }
  ]
}

